window.SAOMD_STORIES[410401401]={"id":410401401,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401401:1:1","speaker":"Reciter","text":"In the early dawn...","pose":2,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"黎明时分……"},{"uid":"410401401:1:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:1:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410401401:2:1","speaker":"Eugeo","text":"This one!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这个！"}]},{"id":3,"order":3,"actions":[{"uid":"410401401:3:1","speaker":"Reciter","text":"When the mists on the Uji River\nslowly lift and clear...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"当宇治川的雾气慢慢消散、散去时……"}]},{"id":4,"order":4,"actions":[{"uid":"410401401:4:1","speaker":"Alice","text":"Incorrect. This one.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不对。这个。"}]},{"id":5,"order":5,"actions":[{"uid":"410401401:5:1","speaker":"Eugeo","text":"Wait, really?\nI thought the next part was\n\"as the moon comes into view\"...?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"等等，真的吗？我以为下一部分是“当月亮进入视野时”......？"}]},{"id":6,"order":6,"actions":[{"uid":"410401401:6:1","speaker":"Kirito","text":"Ha ha, there are two poems that\nbegin with \"in the early dawn.\"","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，有两首诗是“黎明时分”。"},{"uid":"410401401:6:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410401401:7:1","speaker":"Kirito","text":"In karuta, there are a number of\nsets of poems that start the same.\nYou need to be careful.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"在歌牌里，有好几组开头相同的诗。你需要小心。"}]},{"id":8,"order":8,"actions":[{"uid":"410401401:8:1","speaker":"Alice","text":"Eugeo, we already went over this\nearlier. I expected better of you.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧，这个我们之前已经讲过了。我对你抱有更好的期望。"},{"uid":"410401401:8:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":9,"order":9,"actions":[{"uid":"410401401:9:1","speaker":"Eugeo","text":"Y-Yes, ma'am...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是、是的，女士……"}]},{"id":10,"order":10,"actions":[{"uid":"410401401:10:1","speaker":"Asuna","text":"Hehe... Alice seems better than\nEugeo when it comes to memorizing\nthings.","pose":10023004,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵……在记忆方面，爱丽丝似乎比尤吉欧好一些。"},{"uid":"410401401:10:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410401401:11:1","speaker":"Kirito","text":"Yeah, she's really impressive.\nYou and I played this when we were\nkids, so we remember a bunch...","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，她真的很令人印象深刻。你和我小时候都玩过这个，所以我们记得很多......"}]},{"id":12,"order":12,"actions":[{"uid":"410401401:12:1","speaker":"Kirito","text":"But the speed at which she's\nmastering every word and phrase\nis incredible.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是她掌握每一个单词和短语的速度令人难以置信。"}]},{"id":13,"order":13,"actions":[{"uid":"410401401:13:1","speaker":"Alice","text":"Sweet words will earn you nothing\nbut hard stares from me, Kirito.\nNow, quiet. The next card comes...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"甜言蜜语只能换来我桐人的狠狠瞪视。现在，安静。下一张卡来了..."},{"uid":"410401401:13:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410401401:14:1","speaker":"Reciter","text":"If...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"如果……"}]},{"id":15,"order":15,"actions":[{"uid":"410401401:15:1","speaker":"Kirito","text":"This one!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这个！"},{"uid":"410401401:15:2","speaker":"Asuna","text":"","pose":10023003,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401401:16:1","speaker":"Alice","text":"Huh?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"啊？！"},{"uid":"410401401:16:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410401401:17:1","speaker":"Reciter","text":"...I see that bridge...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"……我看到那座桥了……"}]},{"id":18,"order":18,"actions":[{"uid":"410401401:18:1","speaker":"Alice","text":"How did he know it would be \"made\nwhite with a deep-laid frost\"?!\nWe only heard one syllable!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他怎么知道会是“霜白霜”？！我们只听到一个音节！"}]},{"id":19,"order":19,"actions":[{"uid":"410401401:19:1","speaker":"Alice","text":"There are two poems that start\nwith \"if\"...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"有两首以“如果”开头的诗……"}]},{"id":20,"order":20,"actions":[{"uid":"410401401:20:1","speaker":"Asuna","text":"Good point. I think he rushed it\nand got lucky.","pose":10023011,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"说得好。我认为他很匆忙并且很幸运。"},{"uid":"410401401:20:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410401401:21:1","speaker":"Kirito","text":"Nope. No luck here! It was a\nsimple trick someone just taught\nme.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没有。这里运气不好！这是某人刚刚教我的一个简单技巧。"}]},{"id":22,"order":22,"actions":[{"uid":"410401401:22:1","speaker":"Kirito","text":"The intonation of the word is\nslightly different depending on\nwhat word follows.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"根据后面的单词，语调略有不同。"}]},{"id":23,"order":23,"actions":[{"uid":"410401401:23:1","speaker":"Kirito","text":"I'll admit it depends on the\nreciter, but if you know what\nto listen for, it's easy.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我承认这取决于朗诵者，但如果你知道听什么，那就很容易了。"}]},{"id":24,"order":24,"actions":[{"uid":"410401401:24:1","speaker":"Asuna","text":"W-Wow... Ha ha... \"Easy,\" he says.\nIf you're a crazy, superhuman,\ndual-wielding ninja master.","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哇、哇……哈哈……“简单，”他说。如果你是一个疯狂的、超人的、双持的忍者大师。"}]},{"id":25,"order":25,"actions":[{"uid":"410401401:25:1","speaker":"Eugeo","text":"Yeah, there's no way I could pick\nout slight variations in tone like\nthat...","pose":105302052,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是啊，我不可能辨别出那种细微的语气变化……"},{"uid":"410401401:25:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410401401:26:1","speaker":"Alice","text":"Grr... This game is far more\ncomplex than I anticipated...\nMemorization is not enough, is it?","pose":105401022,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"呃……这个游戏比我想象的要复杂得多……记忆力不够吧？"}]},{"id":27,"order":27,"actions":[{"uid":"410401401:27:1","speaker":"Alice","text":"Very well! Teach me all these\nsly tricks and devilish secrets,\nKirito!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"很好！教我所有这些狡猾的伎俩和邪恶的秘密，桐人！"}]},{"id":28,"order":28,"actions":[{"uid":"410401401:28:1","speaker":"Kirito","text":"Ha ha, I'd be happy to.","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，我很乐意。"},{"uid":"410401401:28:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410401401:29:1","speaker":"Kirito","text":"Then again...I'm a bit worried.\nI don't know if it's a great idea\nfor us to sit here practicing...","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"话说回来……我有点担心。我不知道我们坐在这里练习是否是一个好主意......"}]},{"id":30,"order":30,"actions":[{"uid":"410401401:30:1","speaker":"Asuna","text":"Why's that?","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"为什么呢？"}]},{"id":31,"order":31,"actions":[{"uid":"410401401:31:1","speaker":"Kirito","text":"Look, over there. There's a ton\nof people lining up to join the\ntournament.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看那边。有很多人排队参加比赛。"}]},{"id":32,"order":32,"actions":[{"uid":"410401401:32:1","speaker":"Eugeo","text":"Wow, you're right.\nLook at all of them.","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哇，你说得对。看看他们所有人。"},{"uid":"410401401:32:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410401401:33:1","speaker":"Alice","text":"Even if all four of us win many\nmatches, it has become difficult\nto play all the contestants.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"即使我们四个人都赢得了很多比赛，但要与所有参赛者比赛已经变得很困难。"}]},{"id":34,"order":34,"actions":[{"uid":"410401401:34:1","speaker":"Kirito","text":"Yeah... Our purpose here isn't to\nwin this tournament,","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的……我们来这里的目的不是赢得这场比赛，"},{"uid":"410401401:34:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410401401:35:1","speaker":"Kirito","text":"but to play a lot of different\npeople, observe them up close,","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是要扮演很多不同的人，近距离观察他们，"}]},{"id":36,"order":36,"actions":[{"uid":"410401401:36:1","speaker":"Kirito","text":"and discover if our Hi-Mob is\nhiding here.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看看我们的Hi-Mob是否藏在这里。"}]},{"id":37,"order":37,"actions":[{"uid":"410401401:37:1","speaker":"Asuna","text":"Hmm... I have an idea! Let's call\nin backup! I'll see if Sinonon\nand Liz and everyone can come!","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯……我有一个主意！我们呼叫支援吧！我就看看Sinonon和莉兹大家能不能来！"}]},{"id":38,"order":38,"actions":[{"uid":"410401401:38:1","speaker":"Kirito","text":"Great thinking! The more people we\nhave, the better our chances.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好主意！我们拥有的人越多，我们的机会就越大。"}]},{"id":39,"order":39,"actions":[{"uid":"410401401:39:1","speaker":"Liz","text":"Hey-ho! What's up, guys?","pose":10071404,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"嘿嗬！怎么样，伙计们？"},{"uid":"410401401:39:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410401401:40:1","speaker":"Sinon","text":"You called?","pose":10042004,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你打电话来了？"}]},{"id":41,"order":41,"actions":[{"uid":"410401401:41:1","speaker":"Asuna","text":"Wow, you two look SO cute!!","pose":10023004,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哇，你们两个看起来好可爱啊！！"},{"uid":"410401401:41:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410401401:42:1","speaker":"Kirito","text":"Thanks for converting over to\nAsuka Empire to help us.","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谢谢你转投飞鸟帝国来帮助我们。"}]},{"id":43,"order":43,"actions":[{"uid":"410401401:43:1","speaker":"Liz","text":"Eh, it only took like two minutes.\nAnd why didn't you call earlier?\nI thought we were friends.","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"呃，也就两分钟吧。那你为什么不早点打电话呢？我以为我们是朋友。"},{"uid":"410401401:43:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410401401:44:1","speaker":"Sinon","text":"Well, at least you and I had time\ntoday, Liz. No one else was free.","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"好吧，至少你和我今天有时间，莉兹。没有其他人是自由的。"}]},{"id":45,"order":45,"actions":[{"uid":"410401401:45:1","speaker":"Asuna","text":"Seriously, we owe you big time!\nYou're lifesavers!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"说实话，我们欠你一个大人情！你们是救星！"},{"uid":"410401401:45:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410401401:46:1","speaker":"Sinon","text":"Where's Eugeo and Alice?","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"尤吉欧和爱丽丝在哪里？"},{"uid":"410401401:46:2","speaker":"Liz","text":"","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":47,"order":47,"actions":[{"uid":"410401401:47:1","speaker":"Kirito","text":"Over there, at the tournament.\nThey're doing great.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那边，比赛的地方。他们做得很好。"},{"uid":"410401401:47:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410401401:48:1","speaker":"Liz","text":"They're really playing karuta?\nThat game's super hard to pick up.\nAre they getting creamed?","pose":10071408,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"他们真的在玩卡鲁塔吗？这游戏超级难上手啊他们正在涂奶油吗？"},{"uid":"410401401:48:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410401401:49:1","speaker":"Asuna","text":"They both take things really\nseriously, so they've already\nmastered it and are kicking butt.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们俩对待事情都很认真，所以他们已经掌握了并且正在踢屁股。"},{"uid":"410401401:49:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410401401:50:1","speaker":"Kirito","text":"Ha ha, they beat me a bunch\nalready. They're really making\nme look bad.","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，他们已经打败我了。他们真的让我看起来很糟糕。"}]},{"id":51,"order":51,"actions":[{"uid":"410401401:51:1","speaker":"Sinon","text":"Hehe, good to hear.","pose":10042004,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"呵呵，很高兴听到。"},{"uid":"410401401:51:2","speaker":"Liz","text":"","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":52,"order":52,"actions":[{"uid":"410401401:52:1","speaker":"Liz","text":"Well, normally I'd spend a couple\nhours tinkering with my new job\nskills, but let's get our game on!","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"好吧，通常我会花几个小时来修补我的新工作技能，但让我们开始我们的游戏吧！"}]},{"id":53,"order":53,"actions":[{"uid":"410401401:53:1","speaker":"Sinon","text":"Yeah. I picked Gunner myself,\nand I'd love to try it out.","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是的。我自己选择了枪手，我很想尝试一下。"}]},{"id":54,"order":54,"actions":[{"uid":"410401401:54:1","speaker":"Sinon","text":"I was pretty surprised to learn\nthat a game set in old Japan let\nyou use guns.","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"当我得知一款以旧日本为背景的游戏可以使用枪支时，我感到非常惊讶。"}]},{"id":55,"order":55,"actions":[{"uid":"410401401:55:1","speaker":"Liz","text":"I HAD to go with Bladesmith.\nEvery blacksmith dreams about\nbeing able to forge katanas.","pose":10071404,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"我必须和刀匠一起去。每个铁匠都梦想能够锻造武士刀。"}]},{"id":56,"order":56,"actions":[{"uid":"410401401:56:1","speaker":"Kirito","text":"Yeah, those classes fit you two\nlike gloves. I went with a dual-\nwielding samurai: the Swordmaster.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，这些课程就像手套一样适合你们两个。我选择了一位双持武士：剑圣。"},{"uid":"410401401:56:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410401401:57:1","speaker":"Asuna","text":"I was debating going War Maiden,\nbut I ended up picking Blade\nPriestess.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"本来也考虑过要不要女战，最后还是选择了剑圣。"}]},{"id":58,"order":58,"actions":[{"uid":"410401401:58:1","speaker":"Asuna","text":"War Maidens fight bare-handed and\nare really acrobatic, but I feel\nmore comfortable with a sword.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"战女们徒手战斗，确实很杂技，但我觉得用剑更舒服。"}]},{"id":59,"order":59,"actions":[{"uid":"410401401:59:1","speaker":"Kirito","text":"Well, we're not going to be\nfighting for a while yet. We need\nto focus on this tournament now.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我们暂时还不会打架。我们现在需要专注于这场比赛。"}]},{"id":60,"order":60,"actions":[{"uid":"410401401:60:1","speaker":"Liz","text":"Sure, fine. Let's go play some\ncards.","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"当然可以。我们去玩几张牌吧。"},{"uid":"410401401:60:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410401401:61:1","speaker":"Player A","text":"I win.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家A","text_zh":"我赢了。"},{"uid":"410401401:61:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":62,"order":62,"actions":[{"uid":"410401401:62:1","speaker":"Alice","text":"...Yes, you do.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……是的。"}]},{"id":63,"order":63,"actions":[{"uid":"410401401:63:1","speaker":"Eugeo","text":"You lost, Alice?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你输了，爱丽丝？"}]},{"id":64,"order":64,"actions":[{"uid":"410401401:64:1","speaker":"Alice","text":"Yes. My opponent was extremely\nskilled.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是的。我的对手技术非常出色。"}]},{"id":65,"order":65,"actions":[{"uid":"410401401:65:1","speaker":"Eugeo","text":"I lost too. My opponent had\nall the cards memorized perfectly\nand was really quick.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也输了。我的对手把所有的牌都记住了，而且速度非常快。"}]},{"id":66,"order":66,"actions":[{"uid":"410401401:66:1","speaker":"Alice","text":"I encountered a similarly fearsome\nfoe. His abilities were almost\nfrightening.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我遇到了同样可怕的敌人。他的能力几乎令人恐惧。"}]},{"id":67,"order":67,"actions":[{"uid":"410401401:67:1","speaker":"Alice","text":"He was strong, fast, and quick to\nreact. Additionally, his senses\nwere all superhuman...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他身体强壮，速度快，反应快。而且，他的感官都是超人的……"}]},{"id":68,"order":68,"actions":[{"uid":"410401401:68:1","speaker":"Alice","text":"Good point...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"说得好……"}]},{"id":69,"order":69,"actions":[{"uid":"410401401:69:1","speaker":"Eugeo","text":"What is it, Alice?","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"什么啊，爱丽丝？"}]},{"id":70,"order":70,"actions":[{"uid":"410401401:70:1","speaker":"Alice","text":"Nothing. Forget it.\nLet us find Kirito.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"没什么。忘了它。让我们找到桐人。"}]},{"id":71,"order":71,"actions":[{"uid":"410401401:71:1","speaker":"Eugeo","text":"O-Okay, if you're sure...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哦、好吧，如果你确定的话……"}]},{"id":72,"order":72,"actions":[{"uid":"410401401:72:1","speaker":"Kirito","text":"So you played some suspicious\ncharacters?","pose":10012903,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以你演了一些可疑的角色？"},{"uid":"410401401:72:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401401:72:3","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410401401:73:1","speaker":"Alice","text":"Correct. The opponents both Eugeo\nand I faced, along with a few\nothers.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对。我和尤吉欧以及其他几个对手都面对过。"},{"uid":"410401401:73:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:73:3","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410401401:74:1","speaker":"Alice","text":"In fact, there were a number\nof competitors who seemed\nsuspiciously similar.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"其实，有很多看起来相似得可疑的竞争对手。"}]},{"id":75,"order":75,"actions":[{"uid":"410401401:75:1","speaker":"Asuna","text":"Similar? What is that supposed to\nmean?","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"类似？那是什么意思？"},{"uid":"410401401:75:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:75:3","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410401401:76:1","speaker":"Eugeo","text":"All of them had inhumanly-fast\nreaction speeds and had perfectly\nmemorized every card.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们的反应速度快得离人不远，每一张牌都背得很好。"},{"uid":"410401401:76:2","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410401401:76:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410401401:77:1","speaker":"Eugeo","text":"In addition, their senses were\nsuperhuman. Finally, none had\na unique playing style.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"此外，他们的感官也是超人的。最后，没有人有独特的演奏风格。"}]},{"id":78,"order":78,"actions":[{"uid":"410401401:78:1","speaker":"Liz","text":"Oh... I played someone like that\njust now too.","pose":10071408,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"哦……我刚才也扮演过这样的人。"}]},{"id":79,"order":79,"actions":[{"uid":"410401401:79:1","speaker":"Liz","text":"He was really...cold and\ncalculating. He kinda didn't\neven seem human.","pose":10071402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"他真的……冷酷又精于算计。他甚至看起来都不像人类。"}]},{"id":80,"order":80,"actions":[{"uid":"410401401:80:1","speaker":"Sinon","text":"You need physical speed and mental\nagility to play karuta well,","pose":10042002,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你需要身体速度和思维敏捷性才能玩好卡鲁塔，"},{"uid":"410401401:80:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401401:80:3","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":81,"order":81,"actions":[{"uid":"410401401:81:1","speaker":"Sinon","text":"but you also need to come up with\nstrategies or unique playstyles to\ncounter each opponent.","pose":10042002,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"但你也需要想出策略或独特的游戏风格来对抗每个对手。"}]},{"id":82,"order":82,"actions":[{"uid":"410401401:82:1","speaker":"Asuna","text":"Yeah... Like which cards to give\nthem,","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊...比如给他们哪些卡片，"}]},{"id":83,"order":83,"actions":[{"uid":"410401401:83:1","speaker":"Asuna","text":"or how to fake them out and get\nthem to slap the wrong card,\nand so on.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"或者如何假冒他们，让他们打错牌等等。"}]},{"id":84,"order":84,"actions":[{"uid":"410401401:84:1","speaker":"Kirito","text":"So there were a bunch of different\nplayers who all played the same\nway, huh...","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原来是一群不同的玩家，他们的玩法都是一样的啊……"}]},{"id":85,"order":85,"actions":[{"uid":"410401401:85:1","speaker":"Sinon","text":"They were all good, but they all\nseemed inhuman and didn't have\nany unique tricks or strategies...","pose":10042002,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"他们都很好，但都显得不近人情，没有什么独特的招数和策略……"}]},{"id":86,"order":86,"actions":[{"uid":"410401401:86:1","speaker":"Asuna","text":"Interesting. I think we've got\na nice lead on our enemy.","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有趣。我认为我们对敌人已经有了很大的领先优势。"}]},{"id":87,"order":87,"actions":[{"uid":"410401401:87:1","speaker":"Alice","text":"You believe our quarry is among\ntheir number?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你相信我们的猎物就在他们之中吗？"},{"uid":"410401401:87:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:87:3","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410401401:88:1","speaker":"Kirito","text":"Exactly.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。"},{"uid":"410401401:88:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:88:3","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410401401:89:1","speaker":"Eugeo","text":"Okay, but why? Sure, they play\nodd, but how's that tie in to our\nHi-Mob?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好吧，但是为什么呢？当然，他们的表现很奇怪，但这和我们的 Hi-Mob 有什么关系呢？"},{"uid":"410401401:89:2","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410401401:89:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410401401:90:1","speaker":"Kirito","text":"Okay, let me see if I can explain\nit... Our enemy is smart, strong,\nand fast.","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我看看能不能解释一下……我们的敌人很聪明，很强大，而且速度很快。"},{"uid":"410401401:90:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:90:3","speaker":"Asuna","text":"","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401401:91:1","speaker":"Kirito","text":"However, he lacks... How do I put\nthis...? Adaptability? He's not\nvery flexible, I think.","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是，他缺少……怎么说呢……？适应性？我认为他不太灵活。"}]},{"id":92,"order":92,"actions":[{"uid":"410401401:92:1","speaker":"Alice","text":"Interesting. I did get that sense\nfrom our quarry as well. In that\ncase, I agree with you here.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"有趣。我也从我们的采石场那里得到了这种感觉。在这种情况下，我同意你的观点。"},{"uid":"410401401:92:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:92:3","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410401401:93:1","speaker":"Kirito","text":"Yeah. Everyone, keep a close eye\non those guys if you get another\nchance to play them.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。大家如果还有机会和他们比赛的话，请密切关注他们。"},{"uid":"410401401:93:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:93:3","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410401401:94:1","speaker":"Asuna","text":"Since it's not an elimination\ntournament, we still could\nplay one of them again.","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"既然不是淘汰赛，那我们还可以再打一场。"}]},{"id":95,"order":95,"actions":[{"uid":"410401401:95:1","speaker":"Eugeo","text":"Roger that! Alice and I will get\nback to playing, then!","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"收到！ 爱丽丝然后我就回去玩了！"},{"uid":"410401401:95:2","speaker":"Liz","text":"","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410401401:95:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410401401:96:1","speaker":"Alice","text":"Good luck.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"祝你好运。"},{"uid":"410401401:96:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":97,"order":97,"actions":[{"uid":"410401401:97:1","speaker":"Kirito","text":"...","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401401:97:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":98,"order":98,"actions":[{"uid":"410401401:98:1","speaker":"Sinon","text":"Hey... This \"Hi-Mob\" of yours...\nYou said Cardinal made him from\nAlice and Eugeo's data, right?","pose":10042002,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"哎……你这个“Hi-Mob”……你说卡迪纳尔是用爱丽丝和尤吉欧的数据创造出来的吧？"},{"uid":"410401401:98:2","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410401401:99:1","speaker":"Kirito","text":"That's right. And those two are\neffectively no different from a\nhuman from the real world.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。而这两个人实际上与现实世界中的人类没有什么不同。"},{"uid":"410401401:99:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401401:100:1","speaker":"Kirito","text":"But I think even Cardinal can't\nreplicate an AI of their level\nof complexity.","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但我认为即使是卡迪纳尔也无法复制其复杂程度的AI。"}]},{"id":101,"order":101,"actions":[{"uid":"410401401:101:1","speaker":"Kirito","text":"Sure, it can be devious and\nclever, but it's not adaptable.\nThat's its biggest weakness.","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当然，它可以狡猾、聪明，但它的适应能力不强。这是它最大的弱点。"}]},{"id":102,"order":102,"actions":[{"uid":"410401401:102:1","speaker":"Liz","text":"Huh. Well, I think we're close.\nWe'll get that dastardly fiend.","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"嗯。嗯，我想我们已经很接近了。我们会抓住那个卑鄙的恶魔的。"},{"uid":"410401401:102:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401401:103:1","speaker":"Sinon","text":"Oh, yeah. He won't escape us.","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"哦，是的。他不会逃脱我们的。"}]},{"id":104,"order":104,"actions":[{"uid":"410401401:104:1","speaker":"Asuna","text":"Yep! He's as good as caught!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"对！他就等于被抓住了！"},{"uid":"410401401:104:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401401:105:1","speaker":"Player B","text":"...","pose":2,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"玩家B","text_zh":"..."},{"uid":"410401401:105:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410401401:106:1","speaker":"Asuna","text":"...","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."}]},{"id":107,"order":107,"actions":[{"uid":"410401401:107:1","speaker":"Reciter","text":"Winter...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"冬..."}]},{"id":108,"order":108,"actions":[{"uid":"410401401:108:1","speaker":"Asuna","text":"Got it!","pose":10023001,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"知道了！"}]},{"id":109,"order":109,"actions":[{"uid":"410401401:109:1","speaker":"Player B","text":"...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家B","text_zh":"..."}]},{"id":110,"order":110,"actions":[{"uid":"410401401:110:1","speaker":"Reciter","text":"...loneliness in a mountain\nvillage grows only deeper...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"……山村的孤独感只会越来越深……"}]},{"id":111,"order":111,"actions":[{"uid":"410401401:111:1","speaker":"Asuna","text":"There are two poems that start\nwith \"winter,\"","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"以“冬”开头的诗有两首，"}]},{"id":112,"order":112,"actions":[{"uid":"410401401:112:1","speaker":"Asuna","text":"but only the one with that dip in\nintonation at the end of \"winter\"\nis followed by \"loneliness\"!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但只有“冬天”结束时语调低沉的，后面跟着的是“孤独”！"}]},{"id":113,"order":113,"actions":[{"uid":"410401401:113:1","speaker":"Kirito","text":"Asuna's opponent is pretty\nfishy...","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜的对手有点可疑……"}]},{"id":114,"order":114,"actions":[{"uid":"410401401:114:1","speaker":"Kirito","text":"He's fast, smart, and has amazing\nreactions, but he's not trying\nanything to counter Asuna's strat.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他速度快，聪明，反应惊人，但他并没有试图对抗亚丝娜的策略。"}]},{"id":115,"order":115,"actions":[{"uid":"410401401:115:1","speaker":"Kirito","text":"But I've been keeping an eye on\nLiz and Sinon's opponents too, and\nthey both seem pretty robotic...","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不过我也一直在关注莉兹和诗乃的对手，而且他们看起来都很机器人……"}]},{"id":116,"order":116,"actions":[{"uid":"410401401:116:1","speaker":"Kirito","text":"So, there are a bunch of\nsuspicious characters here...\nWhat can that mean...?","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那么，这里有一堆可疑人物……这意味着什么……？"}]},{"id":117,"order":117,"actions":[{"uid":"410401401:117:1","speaker":"Kirito","text":"Wait... Of course! One of my key\nassumptions was wrong!","pose":10012908,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"等等……当然！我的一个关键假设是错误的！"}]},{"id":118,"order":118,"actions":[{"uid":"410401401:118:1","speaker":"Kirito","text":"I was positive he had assumed\nanother form when he converted\nover...","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我确信他在转变后变成了另一种形态……"}]},{"id":119,"order":119,"actions":[{"uid":"410401401:119:1","speaker":"Kirito","text":"But there was nothing stopping\nhim from assuming more than\none form!","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是没有什么能阻止他呈现出不止一种形态！"}]},{"id":120,"order":120,"actions":[{"uid":"410401401:120:1","speaker":"Alice","text":"Kirito...? You're muttering to\nyourself. Is everything all right?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人……？你在自言自语。一切都好吗？"},{"uid":"410401401:120:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:120:3","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401401:121:1","speaker":"Eugeo","text":"Alice and I lost pretty bad just\nnow. Our opponents were really\nsimilar again, too.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝我刚才输得很惨。我们的对手也非常相似。"}]},{"id":122,"order":122,"actions":[{"uid":"410401401:122:1","speaker":"Kirito","text":"So that was his plan... He wanted\nto beat us all quick and force us\nout of the tournament...","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这就是他的计划……他想快速击败我们，迫使我们出局……"}]},{"id":123,"order":123,"actions":[{"uid":"410401401:123:1","speaker":"Kirito","text":"Hey! Hi-Mob! I mean, originally\ncloaked Cait Sith bad guy dude!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂！嗨，暴徒！我的意思是，原来是隐形的猫妖坏人！"}]},{"id":124,"order":124,"actions":[{"uid":"410401401:124:1","speaker":"Eugeo","text":"Um, Kirito? Are you okay?","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，桐人？你还好吗？"}]},{"id":125,"order":125,"actions":[{"uid":"410401401:125:1","speaker":"Kirito","text":"We've seen through your scheme!\nYou've made copies of yourself\nand are hiding in this tournament!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你的阴谋我们已经识破了！你已经复制了自己并躲在了这场锦标赛中！"},{"uid":"410401401:125:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401401:125:3","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410401401:126:1","speaker":"Player B","text":"Good point...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家B","text_zh":"说得好……"}]},{"id":127,"order":127,"actions":[{"uid":"410401401:127:1","speaker":"Asuna","text":"Huh...? Kirito...?\nDo you need to lie down?","pose":10023008,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃……？ 桐人...？需要躺着吗？"}]},{"id":128,"order":128,"actions":[{"uid":"410401401:128:1","speaker":"Player B","text":"Curses!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家B","text_zh":"诅咒！"}]},{"id":129,"order":129,"actions":[{"uid":"410401401:129:1","speaker":"Sinon","text":"Hey, a bunch of these players just\nstarted sprinting at each other...\nThat's...weird.","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"嘿，一群玩家刚刚开始互相冲刺……这……太奇怪了。"},{"uid":"410401401:129:2","speaker":"Liz","text":"","pose":10071408,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410401401:130:1","speaker":"Liz","text":"Am I seeing things?\nThey're merging into one\nperson! That's crazy!","pose":10071401,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"我看到东西了吗？他们合二为一了！太疯狂了！"},{"uid":"410401401:130:2","speaker":"シノン","text":"","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410401401:131:1","speaker":"Hi-Mob","text":"So you saw through my\nplot, did you?!","pose":20370107,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"嗨暴徒","text_zh":"你看穿了我的阴谋吧？！"}]},{"id":132,"order":132,"actions":[{"uid":"410401401:132:1","speaker":"Kirito","text":"There you are! We've been looking\nfor you!","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你来了！我们一直在找你！"},{"uid":"410401401:132:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401401:132:3","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410401401:133:1","speaker":"Asuna","text":"Kirito!","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人！"}]},{"id":134,"order":134,"actions":[{"uid":"410401401:134:1","speaker":"Sinon","text":"Explanation, please?","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"请解释一下？"}]},{"id":135,"order":135,"actions":[{"uid":"410401401:135:1","speaker":"Sinon","text":"After you shouted, a bunch of\nplayers all sprinted at each\nother and merged into one person.","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你一声大喊之后，一群玩家齐齐冲向对方，融合成了一个人。"}]},{"id":136,"order":136,"actions":[{"uid":"410401401:136:1","speaker":"Kirito","text":"Yeah, I think the quest was set to\nresolve when one of us revealed\nthe bad guy's secret.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，我认为当我们中的一个人揭露了坏人的秘密时，任务就已经解决了。"}]},{"id":137,"order":137,"actions":[{"uid":"410401401:137:1","speaker":"Kirito","text":"So shouting out the answer forced\nhim to take his true form.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以喊出答案迫使他显现出本来面目。"}]},{"id":138,"order":138,"actions":[{"uid":"410401401:138:1","speaker":"Liz","text":"Well, that's pretty cheap.\nNo one told me he could\nmake copies of himself.","pose":10071402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"嗯，相当便宜。没有人告诉我他可以复制自己。"},{"uid":"410401401:138:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401401:138:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401401:139:1","speaker":"Alice","text":"I spoke to another player earlier,\nand she told me that there are\nSacred Arts in this world too.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我之前和另一个玩家聊过，她告诉我这个世界上也有神圣术。"}]},{"id":140,"order":140,"actions":[{"uid":"410401401:140:1","speaker":"Alice","text":"Perhaps our quarry used these\n\"Spirit Skills\" to create those\ncopies.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也许我们的猎物就是用这些“灵技”来制作那些副本的。"}]},{"id":141,"order":141,"actions":[{"uid":"410401401:141:1","speaker":"Kirito","text":"Cool. Thanks for the follow-up,\nAlice.","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"酷。感谢您的关注，爱丽丝。"},{"uid":"410401401:141:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401401:141:3","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":142,"order":142,"actions":[{"uid":"410401401:142:1","speaker":"Alice","text":"Y-You're welcome, I suppose...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不、不客气，我想……"},{"uid":"410401401:142:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:142:3","speaker":"Liz","text":"","pose":10071405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":143,"order":143,"actions":[{"uid":"410401401:143:1","speaker":"Eugeo","text":"Well, enough talking! We've got\nhim cornered this time!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好了，说够了！这次我们把他逼到墙角了！"}]},{"id":144,"order":144,"actions":[{"uid":"410401401:144:1","speaker":"Asuna","text":"Come on, everyone! Let's beat this\nguy and get that Divine Object!","pose":10023001,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"大家加油！让我们打败这个家伙并获得神器！"},{"uid":"410401401:144:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:144:3","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":145,"order":145,"actions":[{"uid":"410401401:145:1","speaker":"Kirito","text":"Yeah!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410401401:145:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":146,"order":146,"actions":[{"uid":"410401401:146:1","speaker":"Hi-Mob","text":"Gngh...!","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"嗨暴徒","text_zh":"嘎……！"}]},{"id":147,"order":147,"actions":[{"uid":"410401401:147:1","speaker":"Hi-Mob","text":"","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"嗨暴徒","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410401401:148:1","speaker":"Liz","text":"Ah!\nIs that what I think it is?!","pose":100714082,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"啊！是我想的那样吗？！"},{"uid":"410401401:148:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401401:148:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":149,"order":149,"actions":[{"uid":"410401401:149:1","speaker":"Sinon","text":"He's trying to run!","pose":100420012,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"他想跑！"},{"uid":"410401401:149:2","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401401:149:3","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410401401:150:1","speaker":"Kirito","text":"Asuna! You're up!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜！你起来了！"}]},{"id":151,"order":151,"actions":[{"uid":"410401401:151:1","speaker":"Asuna","text":"Got it! Haaah!!","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"知道了！哈啊！！"},{"uid":"410401401:151:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:151:3","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":152,"order":152,"actions":[{"uid":"410401401:152:1","speaker":"Hi-Mob","text":"What?! How...?!","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"嗨暴徒","text_zh":"什么？！如何...？！"}]},{"id":153,"order":153,"actions":[{"uid":"410401401:153:1","speaker":"Sinon","text":"What did you just do, Asuna?\nWas that an item?!","pose":10042008,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"亚丝娜你刚才做了什么？那是一个物品吗？"},{"uid":"410401401:153:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401401:153:3","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":154,"order":154,"actions":[{"uid":"410401401:154:1","speaker":"Asuna","text":"He got away from us once, so we\ndecided to come prepared this\ntime!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他曾经离开过我们一次，所以我们这次有备而来！"}]},{"id":155,"order":155,"actions":[{"uid":"410401401:155:1","speaker":"Kirito","text":"Yeah. It was originally an SAO\nitem that nullified teleportation\ncrystals.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。它原本是一件使传送水晶无效化的SAO物品。"}]},{"id":156,"order":156,"actions":[{"uid":"410401401:156:1","speaker":"Kirito","text":"I dropped it in my inventory and,\nluckily, it somehow managed to\nconvert over with my character.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我把它放到了我的库存里，幸运的是，它以某种方式成功地与我的角色转换了。"}]},{"id":157,"order":157,"actions":[{"uid":"410401401:157:1","speaker":"Kirito","text":"Asuna and I made a ton of them\nback in ALO after he escaped the\nfirst time, just in case.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜和我在他第一次逃跑后在ALO做了很多，以防万一。"},{"uid":"410401401:157:2","speaker":"Sinon","text":"","pose":10042005,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":158,"order":158,"actions":[{"uid":"410401401:158:1","speaker":"Hi-Mob","text":"M-My warp portal...\nY-You ruined it...!","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"嗨暴徒","text_zh":"我、我的传送门……你、你毁了它……！"}]},{"id":159,"order":159,"actions":[{"uid":"410401401:159:1","speaker":"Alice","text":"Strike him down, now!\nWhile we have the chance!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"打倒他，现在！趁我们还有机会！"},{"uid":"410401401:159:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401401:159:3","speaker":"Liz","text":"","pose":10071407,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":160,"order":160,"actions":[{"uid":"410401401:160:1","speaker":"Kirito","text":"Attaaack!!","pose":10012901,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"攻击！！"},{"uid":"410401401:160:2","speaker":"Sinon","text":"","pose":10042007,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401401:160:3","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":161,"order":161,"actions":[{"uid":"410401401:161:1","speaker":"Urdr","text":"You have found another Divine\nObject...","pose":20330104,"background":"bg_event_urtharbrunnr","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你又发现了一件神物……"}]},{"id":162,"order":162,"actions":[{"uid":"410401401:162:1","speaker":"Kirito","text":"Yup! Only one left to go.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊！只剩下一个人要走了。"},{"uid":"410401401:162:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":163,"order":163,"actions":[{"uid":"410401401:163:1","speaker":"Asuna","text":"Well, I for one am happy we\nwere finally able to finish off\nthat Hi-Mob.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我很高兴我们终于能够干掉那个Hi-Mob了。"}]},{"id":164,"order":164,"actions":[{"uid":"410401401:164:1","speaker":"Alice","text":"I second that. Who would have\nthought we'd have to chase our\nquarry across multiple worlds?","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我同意。谁会想到我们必须跨越多个世界追逐我们的猎物？"},{"uid":"410401401:164:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":165,"order":165,"actions":[{"uid":"410401401:165:1","speaker":"Kirito","text":"I'm just sad we didn't have more\ntime to look around over there.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我只是遗憾我们没有更多的时间去那边看看。"},{"uid":"410401401:165:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":166,"order":166,"actions":[{"uid":"410401401:166:1","speaker":"Eugeo","text":"Ha ha, yeah. We played karuta the\nwhole time and barely even got\nto see the sights!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哈哈，是啊。我们一直在玩卡鲁塔，几乎没有看到景点！"},{"uid":"410401401:166:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":167,"order":167,"actions":[{"uid":"410401401:167:1","speaker":"Asuna","text":"Hehe, if we have time, we can\nalways go back.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，如果有时间的话，我们可以随时回去。"},{"uid":"410401401:167:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":168,"order":168,"actions":[{"uid":"410401401:168:1","speaker":"Kirito","text":"Yeah!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410401401:168:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":169,"order":169,"actions":[{"uid":"410401401:169:1","speaker":"Urdr","text":"Please, brave fairies and warriors\nfrom another world, recover the\nfinal Divine Object.","pose":20330104,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"请来自异世界的勇敢的仙女和战士们，找回最后的神器。"}]},{"id":170,"order":170,"actions":[{"uid":"410401401:170:1","speaker":"Kirito","text":"You can count on us!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"您可以信赖我们！"},{"uid":"410401401:170:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":171,"order":171,"actions":[{"uid":"410401401:171:1","speaker":"Urdr","text":"Lastly...there is one thing\nI feel I must tell you...","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"最后……有一件事我觉得我必须告诉你……"}]},{"id":172,"order":172,"actions":[{"uid":"410401401:172:1","speaker":"Asuna","text":"There is?","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有吗？"},{"uid":"410401401:172:2","speaker":"Kirito","text":"","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":173,"order":173,"actions":[{"uid":"410401401:173:1","speaker":"Urdr","text":"As you know, the Divine Objects\ncontain a power so terrible,\neven we gods fear it.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"如你所知，神器蕴含着可怕的力量，就连我们诸神都害怕它。"}]},{"id":174,"order":174,"actions":[{"uid":"410401401:174:1","speaker":"Kirito","text":"Y-Yeah, go on...","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是、是啊，继续……"},{"uid":"410401401:174:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":175,"order":175,"actions":[{"uid":"410401401:175:1","speaker":"Urdr","text":"Even mere knowledge of this power\ncan lead to calamity.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"即使仅仅了解这种力量也会导致灾难。"}]},{"id":176,"order":176,"actions":[{"uid":"410401401:176:1","speaker":"Urdr","text":"Thus, we gods ensure that all\nthose who come into contact with\nit have their memories erased.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"所以我们诸神保证所有接触过它的人都会被抹去记忆。"}]},{"id":177,"order":177,"actions":[{"uid":"410401401:177:1","speaker":"Alice","text":"Wh-What speed!!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"什、什么速度！！"},{"uid":"410401401:177:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":178,"order":178,"actions":[{"uid":"410401401:178:1","speaker":"Eugeo","text":"You mean...","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你的意思是……"}]},{"id":179,"order":179,"actions":[{"uid":"410401401:179:1","speaker":"Kirito","text":"So in other words, if our memory\nof the Divine Objects is wiped,\nthis won't happen again?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说，如果我们对神器的记忆被抹掉，就不会再出现这种情况了？"},{"uid":"410401401:179:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":180,"order":180,"actions":[{"uid":"410401401:180:1","speaker":"Urdr","text":"That is correct.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"没错。"}]},{"id":181,"order":181,"actions":[{"uid":"410401401:181:1","speaker":"Asuna","text":"Umm... Kirito? The AmuSphere can't\nerase a person's memory...right?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯……桐人？ AmuSphere无法消除人的记忆……对吧？"},{"uid":"410401401:181:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":182,"order":182,"actions":[{"uid":"410401401:182:1","speaker":"Kirito","text":"Y-Yeah... The Augma could kinda\ndo that,","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是、是啊……Augma 可以做到这一点，"}]},{"id":183,"order":183,"actions":[{"uid":"410401401:183:1","speaker":"Kirito","text":"but the AmuSphere shouldn't be\nable to do anything dangerous\nlike that...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是AmuSphere应该不会做出那样危险的事吧……"}]},{"id":184,"order":184,"actions":[{"uid":"410401401:184:1","speaker":"Alice","text":"AmuSphere? Augma?\nWhat are you two talking about?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"AmuSphere？奥格玛？你们两个在说什么？"},{"uid":"410401401:184:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":185,"order":185,"actions":[{"uid":"410401401:185:1","speaker":"Kirito","text":"U-Uh, nothing, Alice...","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃、呃，没什么，爱丽丝……"},{"uid":"410401401:185:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":186,"order":186,"actions":[{"uid":"410401401:186:1","speaker":"Eugeo","text":"I don't want to have my memory\nerased! Is there nothing we can\ndo?","pose":105302062,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我不想我的记忆被抹去！我们无能为力吗？"},{"uid":"410401401:186:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":187,"order":187,"actions":[{"uid":"410401401:187:1","speaker":"Urdr","text":"I am eternally grateful to you.\nHowever, there is no changing\nyour sad fate.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我永远感激你。然而，这并不能改变你悲惨的命运。"}]},{"id":188,"order":188,"actions":[{"uid":"410401401:188:1","speaker":"Urdr","text":"This was decided long ago, when\nthe Divine Objects were first\nforged...","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这在很久以前，神器刚被锻造的时候就已经决定了……"}]},{"id":189,"order":189,"actions":[{"uid":"410401401:189:1","speaker":"Alice","text":"So...this is one of the rules\nof this world...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所以……这就是这个世界的规则之一……"},{"uid":"410401401:189:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":190,"order":190,"actions":[{"uid":"410401401:190:1","speaker":"Alice","text":"In which case, there is truly\nnothing we can do.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这样的话，我们真的没有办法了。"}]},{"id":191,"order":191,"actions":[{"uid":"410401401:191:1","speaker":"Eugeo","text":"You're just going to give up,\nAlice? Sit back and let our\nmemories be destroyed?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝，你就这么放弃吗？坐视我们的记忆被摧毁？"}]},{"id":192,"order":192,"actions":[{"uid":"410401401:192:1","speaker":"Alice","text":"Of course, this does not sit well\nwith me. But we must return to\nour world eventually...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"当然，这不适合我。但我们终究还是要回到自己的世界……"}]},{"id":193,"order":193,"actions":[{"uid":"410401401:193:1","speaker":"Alice","text":"Though our time here was well\nspent, our memories of this place\nare unnecessary in our world.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"虽然我们在这里度过了美好的时光，但这里的记忆在我们的世界里是不必要的。"}]},{"id":194,"order":194,"actions":[{"uid":"410401401:194:1","speaker":"Eugeo","text":"A-Alice!! You can't mean that!","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"A-爱丽丝！！你不可能是这个意思！"}]},{"id":195,"order":195,"actions":[{"uid":"410401401:195:1","speaker":"Asuna","text":"...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."},{"uid":"410401401:195:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":196,"order":196,"actions":[{"uid":"410401401:196:1","speaker":"Kirito","text":"...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."}]}]};
